(function() {
  const GUESS_MIN = 1;
  const GUESS_MAX = 4;
  const STEP_SIZE = 0.5;

  function getMid(lo, hi) {
    return (lo + hi) / 2;
  }

  function bsearch(cmpfunc, arr, target) {
    let lo = 0,
        hi = arr.length - 1;

    while (lo <= hi) {
      const mid = getMid(lo, hi);
      if (cmpfunc(arr[mid], target)) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }

    return arr[lo - 1];
  }

  function calculateSpeed(remainingDistance, timeFirstFour, timeNextTwo, totalTime, tempSpeed) {
    // Calculate the time for the next section with the guess speed.
    const remainingTime = totalTime - timeFirstFour - timeNextTwo;
    const timeNextSection =
      Math.abs(remainingDistance - tempSpeed * totalTime) / tempSpeed;

    // Recalculate the new average speed and check if it matches the target.
    const combinedDistance =
      4 + 2 * (remainingMiles - 4) + remainingDistance;
    const weightedAverageSpeed =
      (combinedDistance / totalTime) * 4 +
      tempSpeed * remainingTime / totalTime;

    if (weightedAverageSpeed === target) {
      return tempSpeed;
    }

    return bsearch(function(speedGuess) {
      return calculateSpeed(remainingDistance, timeFirstFour, timeNextTwo, totalTime, speedGuess) === target;
    }, [GUESS_MIN, GUESS_MAX].map((v) => v * STEP_SIZE), GUESS_MIN);
  }

