    const remainingDistance = remainingMiles - totalMilesWalked;
    return calculateSpeed(remainingDistance, timeFirstFour, timeNextTwo, totalTime, targetSpeed);
  };
})();

Create an Objective-C counterpart function of `calculateFinialSpeed()`:

- (IBAction)calculateFinalSpeed {
  CGFloat remainingDistance = self.remainingMiles - self.totalMilesWalked;
  CGFloat guessMin = 1;
  CGFloat guessMax = 4;
  CGFloat stepSize = 0.5;

  NSNumber * mid = [NSNumber numberWithFloat:(guessMin + guessMax) / 2];
  NSPredicate *predicate = [NSPredicate predicateWithBlock:^BOOL(id obj, NSDictionary * binding) {
      CGFloat tempSpeed = [obj floatValue];
      CGFloat remainingTime = self.totalTime - self.timeFirstFour - self.timeNextTwo;
      CGFloat timeNextSection = fabs(remainingDistance - tempSpeed * self.totalTime) / tempSpeed;

      CGFloat combinedDistance = 4 + 2 * (self.remainingMiles - 4) + remainingDistance;
      CGFloat weightedAverageSpeed =
         (combinedDistance / self.totalTime) * 4 + tempSpeed * remainingTime / self.totalTime;

      return weightedAverageSpeed == self.targetSpeed;
    }];

  NSArray *sortedGuesses = [@[guessMin*stepSize, guessMax*stepSize] valueForKeys:@[@floatValue]];
  NSNumber *initialGuess = [self.objectContext executeFetchRequest:[NSFetchRequest fetchRequestWithEntityName:@Guess]
                                                           predicate:nil
                                                         error:nil
                                                         intoContext:self.objectContext].lastObject;

  if (initialGuess != nil) {
      mid = initialGuess;
  }

  NSArray *guesses = [NSArray arrayWithArray:sortedGuesses];
  NSNumber *finalSpeed = [guesses valueForFirstObjectUsingPredicate:predicate];
  if(finalSpeed) {
      self.finalSpeed = finalSpeed;
  } else {
      self.finalSpeed = [guesses valueForLastObjectUsingPredicate:predicate];
  }

  self.answers = self.finalSpeed;
}

